// ---------- maintenance cycle and alerts of a vehicle ----------
function vhSvc(v) {
  if (!v.svcKm && !v.svcDays) return null;
  const l = (S.vmaint || []).filter(m => m.vehicle === v.id && m.kind === "service").sort((a, b) => b.date.localeCompare(a.date) || b.odo - a.odo)[0];
  if (!l) return { last: null, nextKm: null, nextDate: null, kmLeft: null, daysLeft: null, late: false, due: true, none: true };
  const nextKm = v.svcKm ? l.odo + v.svcKm : null, nextDate = v.svcDays ? addDays(l.date, v.svcDays) : null, kmLeft = nextKm != null ? nextKm - v.odo : null, daysLeft = nextDate ? fcDays(TODAY, nextDate) : null;
  const late = (kmLeft != null && kmLeft < 0) || (daysLeft != null && daysLeft < 0);
  return { last: l, nextKm, nextDate, kmLeft, daysLeft, late, due: late || (kmLeft != null && kmLeft <= VH_SVC_KM) || (daysLeft != null && daysLeft <= FC_WARN_DAYS), none: false };
}
