  list: () => S.vmaint || [], id: m => m.id, title: m => `${m.id} · ${vhName(m.vehicle)}`, sub: m => `${fdate(m.date)} · ${tx(MT_KIND[m.kind])}`, status: () => "on", search: m => `${m.id} ${vhName(m.vehicle)} ${m.desc} ${m.vendor || ""}`,
